import {createGame} from './engine.mjs';
import {riskOptions,projectDecision,decisionInput} from './risk-policy.mjs';
import {RISK_POLICY,canonicalJSON,sha256} from './risk-rules.mjs';
import {composePolicy} from './decision-lab.mjs';
import {nativePolicyResult,readRefCircuit,refEvalData} from './ref-reader.mjs';
import {verifyCircuit,CIRCUIT,decodeBytes} from './tapeout.mjs';
import {riskCircuitDraft} from './risk-circuit.mjs';
const equal=(a,b)=>canonicalJSON(a)===canonicalJSON(b);
export function receiptSnapshot(game){const result={};for(const key of [...Object.keys(createGame()),'route'])if(game[key]!==undefined)result[key]=structuredClone(game[key]);result.history=[];result.last=null;return result;}
export function decisionExplanation(r){if(!r.feasible)return {feasible:false,reason:r.reason};const m=r.signals.model;return {feasible:true,forecast:r.forecast,cash:r.after.cash,reserve:r.after.reserve,available:m.liquid,income:m.income,living:m.living,charges:m.pressure,installments:m.installments,obligations:m.due,remaining:m.after,reserveMonths:m.reserveMonths,signals:{reserve:r.signals.reserve,coverage:r.signals.coverage,installments:r.signals.installments},output:r.localOutput};}
export async function sealDecisionReceipt(state,evidence){const payload={schema:'moneylab-decision-receipt.v2',engineBalanceVersion:22,snapshot:receiptSnapshot(state),evidence:structuredClone(evidence),scope:'Self-contained consistency record, not a signed attestation. Financial inputs are supplied by Money Lab. Independent chain re-read checks the circuit, not game provenance or settlement.'};return {...payload,digest:await sha256(canonicalJSON(payload))};}
export async function verifyDecisionReceipt(value,{expectedDigest,readChain=false,fetcher,read}={}){
 if(!value||value.schema!=='moneylab-decision-receipt.v2'||typeof value.digest!=='string')throw Error('RECEIPT_SCHEMA');
 const {digest,...payload}=value;if(await sha256(canonicalJSON(payload))!==digest)throw Error('RECEIPT_DIGEST');if(expectedDigest&&expectedDigest.toLowerCase()!==digest.toLowerCase())throw Error('EXTERNAL_DIGEST_MISMATCH');
 const {snapshot:s,evidence:e}=payload;if(payload.engineBalanceVersion!==22||s?.balanceVersion!==22||!s.started||!equal(e?.policy,RISK_POLICY)||e.policyHash!==await sha256(canonicalJSON(RISK_POLICY)))throw Error('RECEIPT_POLICY');
 if(!Number.isSafeInteger(e.proof?.blockNumber)||e.proof.blockNumber<1||!equal(e.runId,s.runId)||e.month!==s.month)throw Error('RECEIPT_CONTEXT');
 const projections=riskOptions(s).map(o=>projectDecision(s,o)).filter(r=>r.feasible&&r.forecast);if(!projections.length||e.branches?.length!==projections.length)throw Error('RECEIPT_BRANCHES');
 const gate=e.proof.cases?.find(c=>c.IN0===s.gate?.IN0&&c.IN1===s.gate?.IN1);if(!gate||gate.OUT0!==s.gate.OUT0||!equal(gate,e.existingGate))throw Error('RECEIPT_GATE');
 if(e.nativeProof){const n=e.nativeProof;if(n.chainId!==196||n.contract!==CIRCUIT.address||n.owner!==CIRCUIT.author||n.circuitId!==49||n.blockNumber!==e.proof.blockNumber||!equal(n.shape,[3,1,0,12])||n.netlist!==riskCircuitDraft().netlist||n.cases?.length!==8)throw Error('RECEIPT_NATIVE');for(let i=0;i<8;i++){const c=n.cases.find(c=>c.R===(i&1)&&c.C===((i>>1)&1)&&c.D===((i>>2)&1));if(!c||c.OUT0!==(i===7?1:0)||c.blockNumber!==n.blockNumber||c.calldata!==refEvalData(49,i)||c.method!=='eth_call'||c.chainId!==196||c.contract!==CIRCUIT.address||c.circuitId!==49||decodeBytes(c.rawResult)!==(i===7?'0x01':'0x00'))throw Error('RECEIPT_NATIVE');}}
 const branches=[];for(let i=0;i<projections.length;i++){const p=projections[i],b=e.branches[i],input=decisionInput(s,p.option),result=composePolicy(p.signals,e.proof);if(b.choice!==p.option.choice||!equal(b.input,input)||b.inputHash!==await sha256(canonicalJSON(input))||!equal(b.policyResult,result)||!equal(b.explanation,decisionExplanation(p)))throw Error('RECEIPT_CALCULATION');
 const projection={cash:p.after.cash,reserve:p.after.reserve,nextKnownSurplus:p.signals.model.after,installments:p.signals.model.installments,income:p.signals.model.income};if(!equal(b.projection,projection))throw Error('RECEIPT_PROJECTION');
 if(e.nativeProof){if(e.nativeProof.circuitId!==49||e.nativeProof.blockNumber!==e.proof.blockNumber||!equal(b.nativeResult,nativePolicyResult(p.signals,e.nativeProof))||b.nativeResult.output!==result.output)throw Error('RECEIPT_NATIVE');}else if(b.nativeResult!==null)throw Error('RECEIPT_NATIVE');branches.push({choice:b.choice,...decisionExplanation(p)});}
 let chainStatus='NOT_READ';if(readChain){if(e.source==='illustrative-offline-example')throw Error('ILLUSTRATIVE_ONLY');const block='0x'+e.proof.blockNumber.toString(16),fresh=await verifyCircuit(fetcher,{block});for(const key of ['address','id','chainId','owner','shape','netlist','cases']){const scrub=x=>JSON.parse(JSON.stringify(x,(k,v)=>k==='checkedAt'?undefined:v));if(!equal(scrub(fresh[key]),scrub(e.proof[key])))throw Error('CHAIN_READ_MISMATCH');}
 if(e.nativeProof){const native=await readRefCircuit(49,{block,...(read?{read}:{})});for(const key of ['contract','circuitId','chainId','owner','shape','netlist','cases'])if(!equal(native[key],e.nativeProof[key]))throw Error('NATIVE_CHAIN_MISMATCH');}chainStatus='MATCHED_AT_RECORDED_BLOCK';}
 return {consistency:'MATCHED',externalDigest:expectedDigest?'MATCHED':'NOT_PROVIDED',chainStatus,blockNumber:e.proof.blockNumber,branches,scope:'Input consistency only. No proof of original game state, real-world finances, randomness fairness, reward entitlement or settlement.'};
}
